  external int __place_holder;

  static ffi.Pointer<OrtCustomHandleType> $allocate(
    ffi.Allocator $allocator, {
    required int $place_holder,
  }) => $allocator<OrtCustomHandleType>()..ref.__place_holder = $place_holder;
}

/// \brief Custom thread join function
