    required int num_of_threads,
    required ffi.Pointer<ffi.Char> cache_dir,
    required ffi.Pointer<ffi.Void> context,
    required int enable_opencl_throttling,
    required int enable_dynamic_shapes,
  }) => $allocator<OrtOpenVINOProviderOptions>()
    ..ref.device_type = device_type
    ..ref.enable_npu_fast_compile = enable_npu_fast_compile
    ..ref.device_id = device_id
