  /// Defaults to 0 (false).
  @ffi.Int()
  external int miopen_conv_exhaustive_search;

  /// \brief ROCM memory limit (To use all possible memory pass in maximum size_t)
  /// Defaults to SIZE_MAX.
  /// \note If a ::OrtArenaCfg has been applied, it will override this field
  @ffi.Size()
  external int gpu_mem_limit;

  /// \brief Strategy used to grow the memory arena
  /// 0 = kNextPowerOfTwo<br>
  /// 1 = kSameAsRequested<br>
  /// Defaults to 0.
  /// \note If a ::OrtArenaCfg has been applied, it will override this field
  @ffi.Int()
  external int arena_extend_strategy;

  /// \brief Flag indicating if copying needs to take place on the same stream as the compute stream in the ROCM EP
  /// 0 = Use separate streams for copying and compute.
  /// 1 = Use the same stream for copying and compute.
  /// Defaults to 1.
  /// WARNING: Setting this to 0 may result in data races for some models.
  /// Please see issue #4829 for more details.
  @ffi.Int()
  external int do_copy_in_default_stream;

  /// \brief Flag indicating if there is a user provided compute stream
  /// Defaults to 0.
  @ffi.Int()
  external int has_user_compute_stream;

  /// \brief User provided compute stream.
  /// If provided, please set `has_user_compute_stream` to 1.
  external ffi.Pointer<ffi.Void> user_compute_stream;

  /// \brief ROCM memory arena configuration parameters
  external ffi.Pointer<OrtArenaCfg> default_memory_arena_cfg;

  @ffi.Int()
  external int enable_hip_graph;

  /// \brief Enable TunableOp for using.
  /// Set it to 1/0 to enable/disable TunableOp. Otherwise, it is disabled by default.
  /// This option can be overridden by environment variable ORT_ROCM_TUNABLE_OP_ENABLE.
  @ffi.Int()
  external int tunable_op_enable;

  /// \brief Enable TunableOp for tuning.
  /// Set it to 1/0 to enable/disable TunableOp tuning. Otherwise, it is disabled by default.
  /// This option can be overridden by environment variable ORT_ROCM_TUNABLE_OP_TUNING_ENABLE.
  @ffi.Int()
  external int tunable_op_tuning_enable;

  /// \brief Max tuning duration time limit for each instance of TunableOp.
  /// Defaults to 0 to disable the limit.
  @ffi.Int()
  external int tunable_op_max_tuning_duration_ms;

  static ffi.Pointer<OrtROCMProviderOptions> $allocate(
    ffi.Allocator $allocator, {
    required int device_id,
    required int miopen_conv_exhaustive_search,
    required int gpu_mem_limit,
    required int arena_extend_strategy,
    required int do_copy_in_default_stream,
    required int has_user_compute_stream,
    required ffi.Pointer<ffi.Void> user_compute_stream,
    required ffi.Pointer<OrtArenaCfg> default_memory_arena_cfg,
    required int enable_hip_graph,
    required int tunable_op_enable,
    required int tunable_op_tuning_enable,
    required int tunable_op_max_tuning_duration_ms,
  }) => $allocator<OrtROCMProviderOptions>()
    ..ref.device_id = device_id
    ..ref.miopen_conv_exhaustive_search = miopen_conv_exhaustive_search
    ..ref.gpu_mem_limit = gpu_mem_limit
    ..ref.arena_extend_strategy = arena_extend_strategy
    ..ref.do_copy_in_default_stream = do_copy_in_default_stream
    ..ref.has_user_compute_stream = has_user_compute_stream
    ..ref.user_compute_stream = user_compute_stream
    ..ref.default_memory_arena_cfg = default_memory_arena_cfg
    ..ref.enable_hip_graph = enable_hip_graph
    ..ref.tunable_op_enable = tunable_op_enable
    ..ref.tunable_op_tuning_enable = tunable_op_tuning_enable
    ..ref.tunable_op_max_tuning_duration_ms = tunable_op_max_tuning_duration_ms;
}

